import {FileSystem,SHA,digest} from './core.mjs';
import {MidiTransport} from './midi.mjs';
import {Installer} from './installer.mjs';
import {zip} from './zip.mjs';
const $=id=>document.getElementById(id);let access,transport,installer,busy=false,downloaded=false;const lines=[];
function log(message){lines.push(new Date().toISOString()+' '+message);$('log').textContent=lines.join('\n');$('status').textContent=message;}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}
function update(){const alive=transport&&!transport.closed;$('access').disabled=busy||!!alive;$('input').disabled=busy||!!alive||!access;$('output').disabled=$('input').disabled;$('connect').disabled=busy||!!alive||!access||!$('input').value||!$('output').value;$('disconnect').disabled=busy||!alive;$('inspect').disabled=busy||!alive||installer?.state!=='new';$('backup').disabled=busy||!installer?.backup.size;$('saved').disabled=busy||!downloaded||installer?.state!=='ready';$('risk').disabled=busy||installer?.state!=='ready';$('install').disabled=busy||!alive||installer?.state!=='ready'||!$('saved').checked||!$('risk').checked;$('progress').hidden=!busy;}
async function run(fn){if(busy)return;busy=true;document.body.classList.remove('error');update();try{await fn();}catch(e){document.body.classList.add('error');log('Operação interrompida: '+e.message);}finally{busy=false;update();}}
function reset(){transport?.close();transport=null;installer?.invalidate();installer=null;downloaded=false;$('saved').checked=false;$('risk').checked=false;$('connection').textContent='Desconectada';update();}
function ports(){for(const [kind,collection] of [['input',access.inputs],['output',access.outputs]]){const s=$(kind),old=s.value;s.replaceChildren(new Option('Selecione a porta da Zoom',''));for(const p of collection.values())if(p.state==='connected')s.add(new Option(p.name||p.id,p.id));if([...s.options].some(o=>o.value===old))s.value=old;}update();}
$('access').onclick=()=>run(async()=>{if(!navigator.requestMIDIAccess)throw new Error('Web MIDI não está disponível. Use Edge ou Opera no computador, em HTTPS.');access=await navigator.requestMIDIAccess({sysex:true});if(!access.sysexEnabled)throw new Error('Acesso SysEx não foi autorizado.');access.onstatechange=()=>{if(transport&&(transport.input.state!=='connected'||transport.output.state!=='connected')){transport.close();log('USB desconectado. Uma gravação em curso pode exigir recuperação pelo backup.');}ports();};ports();log('Acesso MIDI autorizado. Escolha a entrada e a saída da sua Zoom.');});
$('input').onchange=update;$('output').onchange=update;
$('connect').onclick=()=>run(async()=>{reset();const input=access.inputs.get($('input').value),output=access.outputs.get($('output').value);if(!input||!output)throw new Error('Selecione as duas portas MIDI.');await input.open();await output.open();transport=new MidiTransport(input,output,()=>{installer?.invalidate();$('connection').textContent='Desconectada';update();});try{const id=await transport.identify();installer=new Installer(new FileSystem(transport,log),()=>transport.identify(),log);$('connection').textContent=id.model+' · '+id.version;log('MS-70CDR 2.10 reconhecida em modo normal. Nenhum arquivo foi gravado.');}catch(e){transport.close();throw e;}});
$('disconnect').onclick=()=>{reset();log('Conexão encerrada.');};
$('inspect').onclick=()=>run(async()=>{const res=await fetch('./assets/FLTDLBS.ZDL',{cache:'no-store'});if(!res.ok)throw new Error('Não foi possível carregar o candidato.');const plan=await installer.inspect(new Uint8Array(await res.arrayBuffer()));$('plan').textContent=plan.mode==='current'?'A versão v0.1.1 já está instalada. Nenhuma gravação é necessária.':plan.mode==='update'?'A versão anterior reconhecida será substituída pela v0.1.1, mantendo o ID 958.':'O ID 958 está livre. FltrDlyB será acrescentado à categoria Delay.';log(plan.mode==='current'?'Versão atual encontrada; instalação desnecessária.':'Leitura concluída. Baixe o backup antes de continuar.');});
$('backup').onclick=()=>run(async()=>{if(!installer?.backup.size)throw new Error('Nenhum arquivo disponível.');const entries=new Map(installer.backup),manifest={app:'MultiStomp USB experimental v0.1',model:'MS-70CDR',firmware:'2.10',created:new Date().toISOString(),complete:installer.backup.size===installer.files?.length,candidateSHA256:SHA,files:[]};for(const [name,data] of entries)manifest.files.push({name,size:data.length,sha256:await digest(data)});entries.set('manifest.json',new TextEncoder().encode(JSON.stringify(manifest,null,2)));download(zip(entries),'MS70CDR-arquivos-'+new Date().toISOString().slice(0,10)+'.zip');downloaded=true;log(manifest.complete?'Backup dos arquivos preparado. Abra o ZIP e confirme abaixo. Os patches não estão incluídos.':'Backup parcial preparado. A instalação continua bloqueada.');});
$('saved').onchange=update;$('risk').onchange=update;
$('install').onclick=()=>run(async()=>{if(!downloaded||!$('saved').checked||!$('risk').checked)throw new Error('Confirme o backup e o teste experimental.');installer.acknowledgeBackup();await installer.install();$('plan').textContent='Arquivos conferidos. Agora desligue e ligue a pedaleira normalmente. Procure FltrDlyB na categoria Delay e comece com BOOST=0.';log('Concluído. Você já pode desligar e ligar normalmente, sem segurar botões. Teste com volume baixo.');});
$('export').onclick=()=>download(new Blob([lines.join('\n')],{type:'text/plain'}),'multistomp-usb-registro.txt');
$('boost').oninput=()=>{const db=Number($('boost').value);$('db').textContent=db;$('gain').textContent=Math.pow(10,db/20).toFixed(3)+'×';};
window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue='';}});
if(!navigator.requestMIDIAccess)$('support').textContent='Este navegador não oferece Web MIDI. Abra no Edge ou Opera em um computador.';
update();
